import 'dart:convert';
import 'dart:typed_data';

import 'package:pointycastle/digests/blake2b.dart';

const _kasDexV5TokenScriptSuffix =
    '';

String kasDexV5TokenBranchScript({
  required Uint8List ownerXOnlyPublicKey,
  required BigInt amount,
}) {
  if (ownerXOnlyPublicKey.length != 32 ||
      amount < BigInt.zero ||
      amount > BigInt.parse('18446744073709551615')) {
    throw ArgumentError('State branch token KasDex tidak valid.');
  }

  final script = BytesBuilder()
    ..add(const [0x6b, 0x20])
    ..add(ownerXOnlyPublicKey)
    ..add(const [0x01, 0x00, 0x08]);
  var remaining = amount;
  for (var index = 0; index < 8; index++) {
    script.addByte((remaining & BigInt.from(255)).toInt());
    remaining >>= 8;
  }
  script
    ..add(const [0x01, 0x00])
    ..add(_hexBytes(_kasDexV5TokenScriptSuffix));
  final digest = Blake2bDigest(
    digestSize: 32,
    key: Uint8List.fromList(utf8.encode('TransactionSigningHash')),
  ).process(script.takeBytes());
  return 'aa20${_hex(digest)}87';
}

Uint8List _hexBytes(String value) => Uint8List.fromList([
  for (var index = 0; index < value.length; index += 2)
    int.parse(value.substring(index, index + 2), radix: 16),
]);

String _hex(List<int> value) =>
    value.map((byte) => byte.toRadixString(16).padLeft(2, '0')).join();
